mapper.select:
SELECT cci.id, cci.name, cci.product_type_id AS productTypeId, cci.type, cci.coupon_code AS couponCode, cci.is_make_physical_card AS isMakePhysicalCard, cci.sold_amount AS soldAmount, cci.available_sale_start_date AS availableSaleStartDate, cci.available_sale_end_date AS availableSaleEndDate FROM coupon_common_info cci
AND is_inservice = #{query.inservice}
AND cci.product_type_id = #{query.productTypeId}
AND cci.type = #{query.type}
ORDER BY cci.type, cci.product_type_id, cci.id

select cci.id, cci.name, cci.sold_amount as packageUnitPrice, pt.id as categoryId, pt.name as categoryName from coupon_common_info cci left join product_type pt on pt.id = cci.product_type_id where cci.type = 5 and cci.is_inservice = 1
and cci.product_type_id = #{categoryId}
and (cci.member_type_id = #{memberTypeId} or cci.member_type_id = 0)
and cci.id in
#{item}
and (isnull(cci.available_sale_start_date) = 1 or (cci.available_sale_start_date <= now() and cci.available_sale_end_date >= now()))
